# Python has dynamic typing where variables can hold any type (int, str, list, dict, etc.) without explicit declaration.
# Built-in types include primitives (int, float, bool, str), collections (list, tuple, dict, set), and special types (None, function, class).
# Type hints (PEP 484) allow optional static type annotations for better code clarity and IDE support: def greet(name: str) -> str: return f"Hello {name}"
